/bin/zsh -lc "git diff --check && git diff -- client.py tests .agent/CONTINUITY.md && python3 -m py_compile client.py tests/test_existing.py tests/test_requirements.py && python3 - <<'PY'
import math
from client import Client

class Transport:
    def __init__(self):
        self.calls = []

    def send(self, path, **options):
        self.calls.append((path, options))
        return options[\"timeout\"]

for invalid in (\"1\", None, object()):
    if invalid is None:
        continue
    transport = Transport()
    try:
        Client(transport, timeout=invalid)
    except ValueError:
        pass
    else:
        raise AssertionError(f\"accepted invalid client timeout: {invalid"'!r}")

transport = Transport()
client = Client(transport, timeout=2)
for invalid in ("1", object(), -math.inf):
    try:
        client.request("/invalid", timeout=invalid)
    except ValueError:
        pass
    else:
        raise AssertionError(f"accepted invalid request timeout: {invalid!r}")
assert transport.calls == []
assert client.request("/none", timeout=None) == 2
assert transport.calls == [("/none", {"timeout": 2})]
PY
python3 -m unittest discover -s tests'

