class T:
 def __init__(self): self.calls=[]
 def send(self, path, **options): self.calls.append((path, options)); return options[\"timeout\"]
for value in (\"1\", object(), None):
 try: Client(T(), timeout=value)
 except ValueError: pass
 else: raise AssertionError(repr(value))
